17 package org.gradle.launcher.daemon.registry;
18 
19 import org.gradle.internal.service.scopes.Scope;
20 import org.gradle.internal.service.scopes.ServiceScope;
21 import org.gradle.util.internal.GFileUtils;
22 import org.gradle.util.GradleVersion;
23 
24 import java.io.File;
25 
26 @ServiceScope(Scope.Global.class)
27 public class DaemonDir {
28     private final File baseDir;
29     private final File versionedDir;
30     private final File registryFile;
31 
32     public DaemonDir(File baseDir) {
33         this.baseDir = baseDir;
34         this.versionedDir = new File(baseDir, GradleVersion.current().getVersion());
35         this.registryFile = new File(versionedDir, "registry.bin");
36         GFileUtils.mkdirs(this.versionedDir);
37     }
38 
39     public File getBaseDir() {
40         return baseDir;
41     }
42 
43     public File getVersionedDir() {
44         return versionedDir;
45     }
46 
47     public File getRegistry() {
48         return registryFile;
49     }
50 }

