16 package org.gradle.launcher.daemon.registry;
17 
18 import org.gradle.cache.Cache;
19 import org.gradle.cache.FileLockManager;
20 import org.gradle.cache.internal.CacheAccessSerializer;
21 import org.gradle.cache.internal.MapBackedCache;
22 import org.gradle.internal.file.Chmod;
23 import org.gradle.internal.service.Provides;
24 import org.gradle.internal.service.ServiceRegistrationProvider;
25 
26 import java.io.File;
27 import java.util.HashMap;
28 import java.util.Map;
29 import java.util.Properties;
30 
31 /**
32  * Takes care of instantiating and wiring together the services required for a daemon registry.
33  */
34 public class DaemonRegistryServices implements ServiceRegistrationProvider {
35     private final File daemonBaseDir;
36     private final Cache<File, DaemonRegistry> daemonRegistryCache;
37 
38     private static final Map<File, DaemonRegistry> REGISTRY_STORAGE = new HashMap<>();
39     private static final Cache<File, DaemonRegistry> REGISTRY_CACHE = new CacheAccessSerializer<>(
40         new MapBackedCache<>(REGISTRY_STORAGE)
41     );
42 
43     public DaemonRegistryServices(File daemonBaseDir) {
44         this(daemonBaseDir, REGISTRY_CACHE);
45     }
46 
47     DaemonRegistryServices(File daemonBaseDir, Cache<File, DaemonRegistry> daemonRegistryCache) {
48         this.daemonBaseDir = daemonBaseDir;
49         this.daemonRegistryCache = daemonRegistryCache;
50     }
51 
52     @Provides
53     DaemonDir createDaemonDir() {
54         return new DaemonDir(daemonBaseDir);
55     }
56 
57     @Provides
58     DaemonRegistry createDaemonRegistry(DaemonDir daemonDir, final FileLockManager fileLockManager, final Chmod chmod) {
59         final File daemonRegistryFile = daemonDir.getRegistry();
60         return daemonRegistryCache.get(daemonRegistryFile, () -> new PersistentDaemonRegistry(daemonRegistryFile, fileLockManager, chmod));
61     }
62 
63     @Provides
64     Properties createProperties() {
65         return System.getProperties();
66     }
67 }
